$.cyN=A.c(["H\u1ecdc, h\u1ecdc n\u1eefa, h\u1ecdc m\xe3i.","Con \u0111\u01b0\u1eddng d\u1eabn \u0111\u1ebfn th\xe0nh c\xf4ng kh\xf4ng bao gi\u1edd l\xe0 con \u0111\u01b0\u1eddng d\u1ec5 d\xe0ng.","H\xe3y bi\u1ebfn kh\xf3 kh\u0103n th\xe0nh \u0111\u1ed9ng l\u1ef1c, v\xe0 bi\u1ebfn th\u1ea5t b\u1ea1i th\xe0nh b\xe0i h\u1ecdc.","Kh\xf4ng c\xf3 g\xec l\xe0 kh\xf4ng th\u1ec3 n\u1ebfu b\u1ea1n quy\u1ebft t\xe2m h\u1ecdc h\u1ecfi v\xe0 l\xe0m vi\u1ec7c ch\u0103m ch\u1ec9.","Tri th\u1ee9c l\xe0 s\u1ee9c m\u1ea1nh, v\xe0 h\u1ecdc t\u1eadp l\xe0 con \u0111\u01b0\u1eddng d\u1eabn \u0111\u1ebfn s\u1ee9c m\u1ea1nh \u0111\xf3.","H\xe3y tin v\xe0o kh\u1ea3 n\u0103ng c\u1ee7a ch\xednh m\xecnh, v\xe0 kh\xf4ng c\xf3 g\xec l\xe0 kh\xf4ng th\u1ec3 \u0111\u1ea1t \u0111\u01b0\u1ee3c.","H\u1ecdc t\u1eadp kh\xf4ng ph\u1ea3i l\xe0 vi\u1ec7c \u0111\u1ec3 c\xf3 k\u1ebft qu\u1ea3, m\xe0 l\xe0 vi\u1ec7c \u0111\u1ec3 ph\xe1t tri\u1ec3n b\u1ea3n th\xe2n.","M\u1ed7i ng\xe0y l\xe0 m\u1ed9t c\u01a1 h\u1ed9i \u0111\u1ec3 h\u1ecdc h\u1ecfi v\xe0 c\u1ea3i thi\u1ec7n b\u1ea3n th\xe2n.","Th\xe0nh c\xf4ng kh\xf4ng \u0111\u1ebfn t\u1eeb nh\u1eefng g\xec b\u1ea1n l\xe0m m\u1ed9t l\u1ea7n, m\xe0 t\u1eeb nh\u1eefng g\xec b\u1ea1n l\xe0m \u0111\u1ec1u \u0111\u1eb7n m\u1ed7i ng\xe0y."],t.s)
$.cyO=function(){var s="Dao c\xf3 m\xe0i m\u1edbi s\u1eafc, ng\u01b0\u1eddi c\xf3 h\u1ecdc m\u1edbi n\xean.",r="D\u1ed1t \u0111\u1ebfn \u0111\xe2u h\u1ecdc l\xe2u c\u0169ng bi\u1ebft.",q="\u0110i m\u1ed9t ng\xe0y \u0111\xe0ng h\u1ecdc m\u1ed9t s\xe0ng kh\xf4n.",p="Hay h\u1ecdc th\xec sang, hay l\xe0m th\xec c\xf3.",o="H\u1ecdc h\xe0nh v\u1ea5t v\u1ea3 k\u1ebft qu\u1ea3 ng\u1ecdt b\xf9i."
return A.c(["C\xf3 h\u1ecdc, c\xf3 kh\xf4n.","Luy\u1ec7n m\xe3i th\xe0nh t\xe0i, mi\u1ec7t m\xe0i t\u1ea5t gi\u1ecfi.","H\u1ecdc \u0103n h\u1ecdc n\xf3i, h\u1ecdc g\xf3i h\u1ecdc m\u1edf.","H\u1ecdc th\u1ea7y ch\u1eb3ng t\u1ea7y h\u1ecdc b\u1ea1n.","H\u1ecdc th\u1ea7y h\u1ecdc b\u1ea1n, v\xf4 v\u1ea1n phong l\u01b0u.",s,r,q,p,"H\u1ecdc l\xe0 h\u1ecdc \u0111\u1ec3 l\xe0m ng\u01b0\u1eddi.",o,"\u0110i\u1ec1u tuy\u1ec7t v\u1eddi nh\u1ea5t c\u1ee7a vi\u1ec7c h\u1ecdc h\xe0nh l\xe0 kh\xf4ng ai c\xf3 th\u1ec3 l\u1ea5y n\xf3 \u0111i kh\u1ecfi b\u1ea1n.","H\u1ecdc kh\xf4ng ph\u1ea3i v\u1ec1 vi\u1ec7c th\u1ebf gi\u1edbi \u0111ang l\xe0m g\xec, m\xe0 l\xe0 nh\u1eefng g\xec b\u1ea1n c\xf3 th\u1ec3 l\xe0m cho n\xf3.","Tr\u1ea3i nghi\u1ec7m l\xe0 c\xe1ch h\u1ecdc t\u1ed1t nh\u1ea5t.","H\u1ecdc v\u1ec1 qu\xe1 kh\u1ee9 n\u1ebfu b\u1ea1n mu\u1ed1n \u0111\u1ecbnh ngh\u0129a t\u01b0\u01a1ng lai.","H\u1ecdc t\u1eadp l\xe0 con m\u1eaft c\u1ee7a tr\xed tu\u1ec7.","N\u1ebfu b\u1ea1n kh\xf4ng mu\u1ed1n h\u1ecdc, kh\xf4ng ai c\xf3 th\u1ec3 gi\xfap b\u1ea1n. N\u1ebfu b\u1ea1n quy\u1ebft t\xe2m h\u1ecdc, kh\xf4ng ai c\xf3 th\u1ec3 ng\u0103n c\u1ea3n b\u1ea1n d\u1eebng l\u1ea1i.","B\u1ea1n lu\xf4n h\u1ecdc \u0111\u01b0\u1ee3c th\u1ee9 g\xec \u0111\xf3 m\u1ed7i ng\xe0y n\u1ebfu b\u1ea1n \u0111\u1ec3 \xfd.","\u0110\u1eebng bao gi\u1edd ng\u1eebng h\u1ecdc t\u1eadp v\xec cu\u1ed9c \u0111\u1eddi kh\xf4ng bao gi\u1edd ng\u1eebng d\u1ea1y.",s," D\u1ed1t \u0111\u1eb7c c\xf2n h\u01a1n hay ch\u1eef l\u1ecfng.",r,q,p,o,"H\u1ecdc t\u1eadp l\xe0 m\u1ed9t kho b\xe1u \u0111i theo ch\u1ee7 nh\xe2n c\u1ee7a n\xf3 t\u1edbi m\u1ecdi n\u01a1i.","Gi\xe1o d\u1ee5c l\xe0 v\u0169 kh\xed m\u1ea1nh nh\u1ea5t ch\xfang ta s\u1eed d\u1ee5ng \u0111\u1ec3 thay \u0111\u1ed5i th\u1ebf gi\u1edbi.","S\u1ed1ng nh\u01b0 th\u1ec3 b\u1ea1n s\u1ebd ch\u1ebft ng\xe0y mai, h\u1ecdc nh\u01b0 th\u1ec3 b\u1ea1n s\u1ebd s\u1ed1ng m\xe3i m\xe3i."],t.s)}()
$.cyP=A.c(["H\u1ecdc t\u1eadp l\xe0 \u0111\u1ea7u t\u01b0 v\xe0o b\u1ea3n th\xe2n, v\xe0 \u0111\xf3 l\xe0 \u0111\u1ea7u t\u01b0 kh\xf4ng bao gi\u1edd l\u1ed7.","M\u1ed7i l\u1ea7n b\u1ea1n c\u1ea3m th\u1ea5y m\xecnh \u0111ang l\xe0m qu\xe1 nhi\u1ec1u, h\xe3y nh\u1edb r\u1eb1ng b\u1ea1n \u0111ang \u0111\u1ea7u t\u01b0 cho t\u01b0\u01a1ng lai c\u1ee7a m\xecnh.","Nh\u1eefng ng\u01b0\u1eddi th\xe0nh c\xf4ng kh\xf4ng ch\u1ec9 l\xe0 nh\u1eefng ng\u01b0\u1eddi th\xf4ng minh, m\xe0 l\xe0 nh\u1eefng ng\u01b0\u1eddi ch\u0103m ch\u1ec9 v\xe0 ki\xean tr\xec.","H\u1ecdc t\u1eadp l\xe0 ch\xeca kh\xf3a m\u1edf ra c\xe1nh c\u1eeda c\u1ee7a th\xe0nh c\xf4ng.","\u0110\u1eebng \u0111\u1ee3i c\u01a1 h\u1ed9i \u0111\u1ebfn, h\xe3y t\u1ea1o ra c\u01a1 h\u1ed9i b\u1eb1ng c\xe1ch h\u1ecdc h\u1ecfi v\xe0 ph\xe1t tri\u1ec3n b\u1ea3n th\xe2n.","Th\xe0nh c\xf4ng l\xe0 k\u1ebft qu\u1ea3 c\u1ee7a s\u1ef1 chu\u1ea9n b\u1ecb, s\u1ef1 ch\u0103m ch\u1ec9 v\xe0 h\u1ecdc h\u1ecfi kh\xf4ng ng\u1eebng.","M\u1ed9t ng\xe0y kh\xf4ng h\u1ecdc h\u1ecfi l\xe0 m\u1ed9t ng\xe0y l\xe3ng ph\xed.","Khi b\u1ea1n ng\u1eebng h\u1ecdc h\u1ecfi, b\u1ea1n b\u1eaft \u0111\u1ea7u \u0111\u1ee9ng y\xean.","Ch\xeca kh\xf3a c\u1ee7a th\xe0nh c\xf4ng n\u1eb1m trong kh\u1ea3 n\u0103ng h\u1ecdc h\u1ecfi v\xe0 th\xedch nghi.","S\u1ef1 th\xf4ng minh kh\xf4ng ph\u1ea3i l\xe0 \u0111i\u1ec1u b\u1ea1n c\xf3, m\xe0 l\xe0 \u0111i\u1ec1u b\u1ea1n l\xe0m v\u1edbi nh\u1eefng g\xec b\u1ea1n h\u1ecdc \u0111\u01b0\u1ee3c."],t.s)
